INSERT INTO products (id, name, slug, description, short_description, status, category_id, created_at) VALUES
  ('66666666-6666-6666-6666-000000000001', 'Áo khoác thể thao zip', 'ao-khoac-the-thao', 'Áo khoác thể thao zip. Chất thun lạnh co giãn 4 chiều, thấm hút mồ hôi nhanh, đường may phẳng không cấn. Tập luyện lẫn đi phố đều thoải mái.', 'Áo khoác thể thao zip — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111101', now() - interval '28 days'),
  ('66666666-6666-6666-6666-000000000002', 'Áo thể thao Hanabi', 'ao-the-thao-hanabi', 'Áo thể thao Hanabi. Chất thun lạnh co giãn 4 chiều, thấm hút mồ hôi nhanh, đường may phẳng không cấn. Tập luyện lẫn đi phố đều thoải mái.', 'Áo thể thao Hanabi — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111101', now() - interval '27 days'),
  ('66666666-6666-6666-6666-000000000003', 'Áo croptop chống nắng cánh dơi', 'ao-croptop-chong-nang', 'Áo croptop chống nắng cánh dơi. Chất thun lạnh co giãn 4 chiều, thấm hút mồ hôi nhanh, đường may phẳng không cấn. Tập luyện lẫn đi phố đều thoải mái.', 'Áo croptop chống nắng cánh dơi — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111101', now() - interval '26 days'),
  ('66666666-6666-6666-6666-000000000004', 'Quần độn mỏng cạp cao chất su mịn', 'quan-don-mong-cap-cao', 'Quần độn mỏng cạp cao chất su mịn. Chất thun lạnh co giãn 4 chiều, thấm hút mồ hôi nhanh, đường may phẳng không cấn. Tập luyện lẫn đi phố đều thoải mái.', 'Quần độn mỏng cạp cao chất su mịn — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111101', now() - interval '25 days'),
  ('66666666-6666-6666-6666-000000000005', 'Set 5 đôi tất Hanabi', 'set-tat-hanabi-5-doi', 'Set 5 đôi tất Hanabi. Chất liệu bền, lành tính với da, giữ form sau nhiều lần giặt. Đóng gói cẩn thận như hình.', 'Set 5 đôi tất Hanabi — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111102', now() - interval '24 days'),
  ('66666666-6666-6666-6666-000000000006', 'Khẩu trang chống nắng UV UPF50', 'khau-trang-chong-nang-uv', 'Khẩu trang chống nắng UV UPF50. Chất liệu bền, lành tính với da, giữ form sau nhiều lần giặt. Đóng gói cẩn thận như hình.', 'Khẩu trang chống nắng UV UPF50 — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111102', now() - interval '23 days'),
  ('66666666-6666-6666-6666-000000000007', 'Khẩu trang vành che nắng 3D kháng khuẩn', 'khau-trang-vanh-che-3d', 'Khẩu trang vành che nắng 3D kháng khuẩn. Chất liệu bền, lành tính với da, giữ form sau nhiều lần giặt. Đóng gói cẩn thận như hình.', 'Khẩu trang vành che nắng 3D kháng khuẩn — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111102', now() - interval '22 days'),
  ('66666666-6666-6666-6666-000000000008', 'Dép da xỏ ngón', 'dep-da-xo-ngon', 'Dép da xỏ ngón. Chất liệu bền, lành tính với da, giữ form sau nhiều lần giặt. Đóng gói cẩn thận như hình.', 'Dép da xỏ ngón — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111102', now() - interval '21 days'),
  ('66666666-6666-6666-6666-000000000009', 'Tất gấu cổ ngắn kèm túi rút', 'tat-gau-co-ngan-tui-rut', 'Tất gấu cổ ngắn kèm túi rút. Chất liệu bền, lành tính với da, giữ form sau nhiều lần giặt. Đóng gói cẩn thận như hình.', 'Tất gấu cổ ngắn kèm túi rút — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111102', now() - interval '20 days'),
  ('66666666-6666-6666-6666-000000000010', 'Hộp 5 đôi dán ngực silicon hoa', 'dan-nguc-silicon-5-doi', 'Hộp 5 đôi dán ngực silicon hoa. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Hộp 5 đôi dán ngực silicon hoa — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '19 days'),
  ('66666666-6666-6666-6666-000000000011', 'Miếng dán ti silicone tai thỏ Hanabi', 'dan-ti-silicone-hanabi', 'Miếng dán ti silicone tai thỏ Hanabi. Chất liệu bền, lành tính với da, giữ form sau nhiều lần giặt. Đóng gói cẩn thận như hình.', 'Miếng dán ti silicone tai thỏ Hanabi — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111102', now() - interval '18 days'),
  ('66666666-6666-6666-6666-000000000012', 'Áo lót su đúc không gọng đệm mỏng', 'ao-lot-su-duc-khong-gong', 'Áo lót su đúc không gọng đệm mỏng. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Áo lót su đúc không gọng đệm mỏng — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '17 days'),
  ('66666666-6666-6666-6666-000000000013', 'Áo ngực su đúc không gọng đệm 3cm', 'ao-nguc-su-duc-nang', 'Áo ngực su đúc không gọng đệm 3cm. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Áo ngực su đúc không gọng đệm 3cm — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '16 days'),
  ('66666666-6666-6666-6666-000000000014', 'Đai nịt bụng thông hơi chống cuộn', 'dai-nit-bung-thong-hoi', 'Đai nịt bụng thông hơi chống cuộn. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Đai nịt bụng thông hơi chống cuộn — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '15 days'),
  ('66666666-6666-6666-6666-000000000015', 'Dây áo ngực trong suốt móc sắt', 'day-ao-nguc-trong-suot', 'Dây áo ngực trong suốt móc sắt. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Dây áo ngực trong suốt móc sắt — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '14 days'),
  ('66666666-6666-6666-6666-000000000016', 'Gen nịt bụng latex định hình eo', 'gen-nit-bung-latex', 'Gen nịt bụng latex định hình eo. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Gen nịt bụng latex định hình eo — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '13 days'),
  ('66666666-6666-6666-6666-000000000017', 'Quần gen nịt bụng đúc su móc cài', 'quan-gen-nit-bung-moc-cai', 'Quần gen nịt bụng đúc su móc cài. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Quần gen nịt bụng đúc su móc cài — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '12 days'),
  ('66666666-6666-6666-6666-000000000018', 'Quần nano sinh nhiệt tan mỡ bụng', 'quan-nano-sinh-nhiet-tan-mo', 'Quần nano sinh nhiệt tan mỡ bụng. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Quần nano sinh nhiệt tan mỡ bụng — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '11 days'),
  ('66666666-6666-6666-6666-000000000019', 'Quần lót cotton không đường may', 'quan-lot-cotton-khong-duong-may', 'Quần lót cotton không đường may. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Quần lót cotton không đường may — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '10 days'),
  ('66666666-6666-6666-6666-000000000020', 'Quần lót mặc trong váy chống lộ', 'quan-lot-mac-trong-vay', 'Quần lót mặc trong váy chống lộ. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Quần lót mặc trong váy chống lộ — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '9 days'),
  ('66666666-6666-6666-6666-000000000021', 'Quần lót Air tăng hình lai băng siêu nhẹ', 'quan-lot-air-tang-hinh', 'Quần lót Air tăng hình lai băng siêu nhẹ. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Quần lót Air tăng hình lai băng siêu nhẹ — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '8 days'),
  ('66666666-6666-6666-6666-000000000022', 'Quần lót cotton kháng khuẩn', 'quan-lot-cotton-khang-khuan', 'Quần lót cotton kháng khuẩn. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Quần lót cotton kháng khuẩn — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '7 days'),
  ('66666666-6666-6666-6666-000000000023', 'Quần lót đúc su tăng hình chống lộ vi', 'quan-lot-duc-su-chong-lo', 'Quần lót đúc su tăng hình chống lộ vi. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Quần lót đúc su tăng hình chống lộ vi — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '6 days'),
  ('66666666-6666-6666-6666-000000000024', 'Quần lót Hanabi su lụa cao cấp', 'quan-lot-hanabi-su-lua', 'Quần lót Hanabi su lụa cao cấp. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Quần lót Hanabi su lụa cao cấp — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '5 days'),
  ('66666666-6666-6666-6666-000000000025', 'Quần lót đúc su tím thun lụa', 'quan-lot-duc-su-tim', 'Quần lót đúc su tím thun lụa. Chất liệu su đúc/cotton mềm mại, co giãn 4 chiều, không hằn khi mặc trong váy hay quần slim fit. Giặt máy được, giữ dáng sau nhiều lần giặt.', 'Quần lót đúc su tím thun lụa — giá tốt, chất như mô tả, đổi trả 30 ngày.', 'ACTIVE', '11111111-1111-1111-1111-111111111103', now() - interval '4 days'),
